{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"LA Rent Stabilization Ordinance allowable rent increase","requirement":"Landlords of RSO-covered units may raise rent only once every 12 months by the LAHD allowable percentage; from February 2, 2026 no extra utility percentage increase is allowed. Increases were barred March 30, 2020 through January 31, 2024.","key_value":"One increase per 12 months at the allowable percentage set by LAHD","coverage_conditions":"Rental properties first built on or before October 1, 1978, and replacement units, including apartments, condominiums, townhomes, duplexes, two or more single-family units on one parcel, ADUs, JADUs, long-term hotel rooms, and mobile homes.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Replacement units under LAMC Section 151.28; condominium and townhome rent amounts not regulated for tenancies commencing after December 31, 1995."},"exemptions":"Condominium and townhome rents for tenancies commencing after December 31, 1995; luxury exemption where the monthly rent charged on or before May 31, 1978 meets the threshold; temporary exemptions.","penalty":null,"effective_date":"2026-02-02","citation":"L.A. Mun. Code § 151 et seq. (Rent Stabilization Ordinance)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"LA RSO legal reasons for eviction and notice filing","requirement":"Under the RSO a landlord may evict only for the listed at-fault or no-fault reasons, must file every termination notice with LAHD within three business days of service, and must pay relocation assistance for no-fault evictions.","key_value":"Notice filed with LAHD within 3 business days of service","coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance (RSO).","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"L.A. Mun. Code § 151.09","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant","interaction":"Units not covered by the RSO are governed by the City's separate Just Cause Ordinance.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
